  function mcqAssignedTopic(subject, set, question = null) {
    const topics = studyTopics(subject);
    const known = id => topics.some(t => t.id === id) ? id : null;
    const explicit = question && known(question.topicId) || known(set.topicId);
    if (explicit) return explicit;
    const labels = [question && question.topicText, question && question.topic,
      set.topicText, set.topic, set.title].filter(Boolean);
    for (const text of labels) {
      const matched = matchTopic(subject, String(text));
      if (matched && known(matched)) return matched;
      const normalized = norm(text);
      const chapter = normalized.match(/\b(?:chapter|topic|module|t)\s*0?(\d+)\b/i);
      if (chapter) {
        const key = 't' + Number(chapter[1]);
        if (known(key)) return key;
        const mapped = topics.find(t => norm(t.code || '') === key);
        if (mapped) return mapped.id;
      }
      const titleMatch = topics.find(t => {
        const a = norm(t.title || '');
        return a.length > 10 && normalized.length > 12 &&
          (normalized.includes(a) || a.includes(normalized));
      });
      if (titleMatch) return titleMatch.id;
    }
    return null;
  }
