    const answer = q && Array.isArray(q.choices) ? psPlain(q.choices.find((c,i)=>mxChoiceKey(c,i)===q.key)||'').replace(/^\s*[A-Da-d]\s*[.)\]]\s*/, '') : '';
    const stem = prompt+'\n'+String(answer).normalize('NFKC').toLowerCase().replace(/\s+/g,' ').trim();
