    const [kind,setKind]=useState(()=>localPref(`nlmKind_${subject.id}`,({concepts:'theory',accounting:'calc',finance:'calc',quantitative:'calc',humanities:'history',science:'science'}[bsa46ProfileId(subject)]||nlmGuessKind(subject))));
