  /* ----- Lectures tab ----- */
  /* =====================================================================
     Lecture spaced repetition.
     A lecture had one boolean: done. But prose is forgotten faster than cards,
     and "I read that once in October" is how a topic quietly rots. Marking one
     studied now schedules a re-skim at 3, 10, 30 then 60 days — short looks,
     not re-reading, which is the point.
     ===================================================================== */
  const LX_STEPS = [3, 10, 30, 60, 120];
  const lxDue = (l) => (l.rv && l.rv.due) || null;
  const lxIsDue = (l) => !!(l.done && lxDue(l) && lxDue(l) <= today());
  function lxStudied(l, again) {
    const n = again ? 0 : Math.min(LX_STEPS.length - 1, ((l.rv && l.rv.n) || 0) + (l.done ? 1 : 0));
    return { n, due: addDays(today(), LX_STEPS[n]), last: today() };
  }
  function lxDueList(subject) {
    return (subject.lectures || []).filter(lxIsDue).sort((a, b) => lxDue(a) < lxDue(b) ? -1 : 1);
  }
  function LxDueChip({ l }) {
    const d = lxDue(l);
    if (!l.done || !d) return null;
    const n = daysUntil(d);
    return h("span", { className: "lx-due" + (n <= 0 ? " now" : "") }, h(Icon, { name: "calendar", size: 12 }), n <= 0 ? "Re-skim now" : n === 1 ? "Re-skim tomorrow" : "Re-skim in " + plural(n, "day"));
  }

  /* ----- lecture and problem set cross-links -----
     p.subtopic and lecture section headings are both free text about the same
     concepts. Matching them means a missed problem is two taps from the exact
     paragraph that governs it, which is a much tighter loop than "go find it". */
  function xrefLecture(subject, p, setTopicId) {
    const pool = (subject.lectures || []).filter((l) => !setTopicId || !l.topicId || l.topicId === setTopicId);
    if (!pool.length) return null;
    const want = norm(p.subtopic || p.title || "");
    if (!want) return null;
    const words = want.split(" ").filter((w) => w.length > 3);
    let best = null;
    for (const l of pool) {
      for (const sec of l.sections || []) {
        const hd = norm(sec.h || "");
        if (!hd) continue;
        let score = 0;
        if (hd === want) score = 100;
        else if (hd.includes(want) || want.includes(hd)) score = 60;
        else score = words.filter((w) => hd.includes(w)).length * 12;
        if (l.topicId && l.topicId === setTopicId) score += 8;
        if (score >= 24 && (!best || score > best.score)) best = { l, sec, score };
      }
    }
    return best;
  }


  /* v23: explicitly triggered, source-grounded generation. Never called on mount. */
