    const [topic,setTopic]=useState(''),[promptText,setPromptText]=useState(''),[answer,setAnswer]=useState(''),[reason,setReason]=useState(''),[quality,setQuality]=useState('again');
    const [filter,setFilter]=useState('due'),[examAnswers,setExamAnswers]=useState({}),[examSubmitted,setExamSubmitted]=useState(false),[examStarted,setExamStarted]=useState(false);
    const [examMinutes,setExamMinutes]=useState(20),[remaining,setRemaining]=useState(1200);
    const examCaptured=useRef(false);
    const [journal,setJournal]=useState(()=>{try{return JSON.parse(localStorage.getItem('bsa_journal_v37_'+subject.id)||'[]')}catch(e){return []}});
    const [account,setAccount]=useState(''),[debit,setDebit]=useState(''),[credit,setCredit]=useState(''),[memo,setMemo]=useState('');
    useEffect(()=>{try{localStorage.setItem(key,JSON.stringify(records))}catch(e){toast('Review storage full: export your backup.')}},[records]);
    useEffect(()=>{try{localStorage.setItem('bsa_journal_v37_'+subject.id,JSON.stringify(journal))}catch(e){toast('Journal storage full: export your backup.')}},[journal,subject.id]);
    useEffect(()=>{if(!examStarted||examSubmitted||mode!=='exam')return;const t=setInterval(()=>setRemaining(v=>Math.max(0,v-1)),1000);return()=>clearInterval(t)},[examStarted,examSubmitted,mode]);
    const due=records.filter(r=>r.subjectId===subject.id&&r.due<=Date.now());
    const current=records.filter(r=>r.subjectId===subject.id).sort((a,b)=>a.due-b.due);
    const add=()=>{if(!topic.trim()||!promptText.trim()){toast('Enter a topic and a question or mistake.');return}const now=Date.now();setRecords(p=>[{id:'r'+now,subjectId:subject.id,topic:topic.trim(),prompt:promptText.trim(),answer,reason,interval:1,attempts:0,due:now,created:now},...p]);setTopic('');setPromptText('');setAnswer('');setReason('');toast('Added to review queue')};
    const review=(r,grade)=>{grantFlashcardReviewXp(r.id);const interval=grade==='again'?1:grade==='hard'?Math.max(2,Math.round((r.interval||1)*1.3)):grade==='good'?Math.max(3,Math.round((r.interval||1)*2.2)):Math.max(5,Math.round((r.interval||1)*3.5));setRecords(p=>p.map(x=>x.id===r.id?{...x,interval,attempts:(x.attempts||0)+1,due:Date.now()+interval*86400000,lastGrade:grade}:x));toast('Next review in '+interval+' day(s)')};
    const cards=(subject.cards||[]).filter(c=>c.q&&c.a).slice(0,20);
    const addCardsToQueue=()=>{const now=Date.now();let added=0;setRecords(prev=>{const next=prev.slice();(subject.cards||[]).filter(c=>c.q&&c.a).forEach((c,i)=>{if(next.some(r=>r.subjectId===subject.id&&r.prompt===c.q))return;next.push({id:'card_'+subject.id+'_'+i+'_'+now,subjectId:subject.id,topic:'Flashcards',prompt:c.q,answer:c.a,reason:'Imported from Concept Vault',interval:1,attempts:0,due:now,created:now});added++});return next});toast(added+' flashcards queued for review')};
    const addProblemsToQueue=()=>{const now=Date.now();let added=0;setRecords(prev=>{const next=prev.slice();(subject.psets||[]).forEach((set,si)=>(set.problems||[]).forEach((pr,i)=>{const question=String(pr.q||pr.question||pr.prompt||pr.text||'').trim();if(!question||next.some(r=>r.subjectId===subject.id&&r.prompt===question))return;next.push({id:'problem_'+subject.id+'_'+si+'_'+i+'_'+now,subjectId:subject.id,topic:set.title||'Problem set',prompt:question,answer:String(pr.answer||pr.ans||pr.solution||'')||'Check your source problem set',reason:'Imported from Problem Sets · verify the worked solution',interval:1,attempts:0,due:now,created:now});added++}));return next});toast(added+' problem-set questions added to Review Queue')};
    // v46: lecture self-checks are first-class spaced-review items.
    const addLectureChecksToQueue=()=>{const now=Date.now();let added=0;setRecords(prev=>{const next=prev.slice();(subject.lectures||[]).forEach((lecture,li)=>(lecture.checks||[]).forEach((check,ci)=>{const question=String(check.q||'').trim();if(!question||next.some(r=>r.subjectId===subject.id&&r.prompt===question))return;next.push({id:'lecture_'+subject.id+'_'+li+'_'+ci+'_'+now,subjectId:subject.id,topic:lecture.title||'Lecture review',prompt:question,answer:String(check.a||''),reason:'Imported from lecture self-checks',interval:1,attempts:0,due:now,created:now});added++}));return next});toast(added+' lecture questions queued for review')};
    const importAttemptsToQueue=()=>{const now=Date.now();let added=0;let attempts=[];try{attempts=JSON.parse(localStorage.getItem('bsa_foundation_attempts_v30')||'[]')}catch(e){};setRecords(prev=>{const next=prev.slice();attempts.filter(a=>a.subjectId===subject.id&&a.prompt&&a.rating!=='independent').forEach((a,i)=>{if(next.some(r=>r.subjectId===subject.id&&r.prompt===a.prompt))return;next.push({id:'attempt_'+subject.id+'_'+i+'_'+now,subjectId:subject.id,topic:a.topic||'Solve & Review',prompt:a.prompt,answer:a.lesson||a.work||'',reason:'Imported from assisted/incorrect practice attempt',interval:1,attempts:0,due:now,created:now});added++});return next});toast(added+' practice attempts added to Review Queue')};
    const addExamMistakes=()=>{const now=Date.now();let added=0;setRecords(prev=>{const next=prev.slice();cards.forEach((c,i)=>{if(examCorrect(examAnswers[i],c.a)||next.some(r=>r.subjectId===subject.id&&r.prompt===c.q))return;next.push({id:'exam_'+subject.id+'_'+i+'_'+now,subjectId:subject.id,topic:'Exam corrections',prompt:c.q,answer:c.a,reason:'My exam answer: '+(examAnswers[i]||'(blank)'),interval:1,attempts:0,due:now,created:now});added++});return next});toast(added+' missed questions added to Review Queue')};
    useEffect(()=>{if(examStarted&&remaining===0)setExamSubmitted(true)},[remaining,examStarted]);
