    const examCorrect=(a,b)=>{const x=normalizeExam(a),y=normalizeExam(b);if(!x||!y)return false;if(x===y)return true;const nx=Number(x.replace(/%$/,'')),ny=Number(y.replace(/%$/,''));return Number.isFinite(nx)&&Number.isFinite(ny)&&x.match(/^[-+]?\d+(?:\.\d+)?%?$/)&&y.match(/^[-+]?\d+(?:\.\d+)?%?$/)&&Math.abs(nx-ny)<1e-7&&x.endsWith('%')===y.endsWith('%')};
