  function HowToCorner({go}) {
    const guides=[
      ['Getting started','Choose your subject in the left sidebar. Today is your starting page; the sidebar opens the other tools.','home'],
      ['Study Toolkit','Open Study Toolkit for the focus timer, handwriting notebook, accounting tools, formulas, and other study utilities.','toolkit'],
      ['Handwriting & zoom','Study Toolkit → Handwriting. Adjust pen size using the 1–24 px slider. Use Zoom (50–300%) or +/− to magnify the paper. Scroll inside the paper area to pan. Pen draws editable new strokes; Select moves them. Eraser removes touched editable objects and paints over older raster ink. Use the shape buttons for T-accounts and double lines.','toolkit'],
      ['Notebook pages & PDF','In Handwriting, use + Page, Rename, Duplicate, Move and the page sidebar. Export PNG, Print page / PDF, or Print all pages / PDF. Backup notebook saves its pages as JSON.','toolkit'],
      ['Flashcards and Concept Vault','Use Concept Vault to organize cards. Use Practice to review them, and rate difficult cards Again so they can be reviewed.','vault'],
      ['Mistake Notebook','Mistake log shows captured errors. Not every quiz mode is guaranteed to capture mistakes automatically; add any missing ones manually.','mistakes'],
      ['Review & exams','Practice contains review activities and exam-style practice. Check the selected subject before starting.','practice'],
      ['Journal entries & T-accounts','Study Toolkit contains accounting practice, transaction-based journal entries and the T-account ledger. Journal totals must balance, but that does not prove account selection is correct.','toolkit'],
      ['10-column worksheet','Study Toolkit → 10-column worksheet. Add account rows, enter TB and adjustment amounts, inspect column totals and row reconciliation, then export CSV or print.','toolkit'],
      ['Lectures, problems and grades','Use Lectures to keep lesson notes, Problem sets for worked practice, and Grades to monitor your results.','lectures'],
      ['Protect your data','Export a study-data backup before updating your website or switching devices. Notebook backups are separate. Do not clear browser storage without confirming a successful backup.','home'],
      ['Dashboard AI guide','Open How-To Corner → Ask about this dashboard, or Ask → Dashboard Guide. This uses your connected Gemini API and the app navigation map; it does not automatically read your private notes.','ask'],
      ['Full screen on iPad','Open Handwriting and tap Fullscreen. Use the zoom controls for larger writing. Tap Exit fullscreen or press Esc on a keyboard. Physical Apple Pencil behavior has not been verified.','toolkit']
    ];
    const [query,setQuery]=useState('');
    const [open,setOpen]=useState(2);
    const shown=guides.map((g,i)=>({g,i})).filter(({g})=>(g[0]+' '+g[1]).toLowerCase().includes(query.toLowerCase()));
    return h('section',{className:'toolkit-panel howto-corner'},
      h('h2',null,'How-To Corner'),
      h('p',{className:'muted'},'A searchable guide to your Study Desk. Open any topic, then use Go to tool to jump there.'),
      h('div',{className:'formula-card'},h('h3',null,'Ask the dashboard AI'),h('p',null,'Need help finding a tool? Ask Gemini with the dashboard guide as context. Requires your existing Gemini API connection.'),h('button',{className:'btn primary',onClick:()=>{setLocalPref('askMode','dashboard');go('ask')}},'Ask about this dashboard')),
      h('input',{type:'search',placeholder:'Search: handwriting, zoom, journal, PDF, backup...',value:query,onChange:e=>setQuery(e.target.value),style:{width:'100%',maxWidth:'620px',marginBottom:'1rem',padding:'.8rem'}}),
      ...shown.map(({g,i})=>h('details',{key:i,open:open===i,onToggle:e=>{if(e.currentTarget.open)setOpen(i);else if(open===i)setOpen(-1)},className:'formula-card',style:{marginBottom:'.7rem'}},
        h('summary',null,h('strong',null,g[0])),
        h('div',{className:'formula-detail'},h('p',null,g[1]),h('button',{className:'btn primary',onClick:()=>go(g[2])},'Go to '+g[2])))),
      !shown.length&&h('p',{className:'muted'},'No matching guides. Try a shorter search.')
    );
  }
  /* Break activities are intentionally local UI state: no study stats are written. */
  /* v87: isolated progression ledger. No historical data is converted to XP. */
  const PROGRESS_KEY='bsa-academic-progress-v1';
  const ACADEMIC_RANKS=[['Beginner',0],['Learner',500],['Scholar',1500],['Analyst',3500],['Strategist',6500],['Master Scholar',10000]];
  const readProgress=()=>{try{const x=JSON.parse(localStorage.getItem(PROGRESS_KEY)||'null');return x&&Array.isArray(x.events)?{...x,events:x.events.filter(e=>e&&typeof e==='object'&&!Array.isArray(e)&&typeof e.id==='string'&&typeof e.kind==='string'&&Number.isFinite(Number(e.xp))&&Number(e.xp)>=0)}:{events:[]};}catch(e){return {events:[]};}};
  const progressTotal=p=>p.events.reduce((a,e)=>a+(Number.isFinite(Number(e.xp))?Math.max(0,Number(e.xp)):0),0);
  const progressRank=x=>ACADEMIC_RANKS.reduce((a,r)=>x>=r[1]?r:a,ACADEMIC_RANKS[0]);
  function grantFocusXp(minutes,uniqueId){
    if(window.__BSA_READ_ONLY__||minutes<10)return;
    try{
      const p=readProgress(),day=new Date().toLocaleDateString('en-CA');
      if(p.events.some(e=>e.id===uniqueId))return;
      const todayXp=p.events.filter(e=>e.day===day&&e.kind==='focus').reduce((a,e)=>a+Math.max(0,Number(e.xp)||0),0);
      const xp=Math.max(0,Math.min(100-todayXp,Math.floor(minutes/10)*10));
      if(!xp)return;
      p.events.push({id:uniqueId,day,kind:'focus',xp,minutes,at:Date.now()});
      localStorage.setItem(PROGRESS_KEY,JSON.stringify(p));
      window.dispatchEvent(new Event('bsa-progress-updated'));
    }catch(e){console.warn('XP not saved',e);}
  }
  // Activity XP is independent of time totals; event IDs make rewards idempotent.
  function grantActivityXp(kind, id, amount, dailyLimit){
    if(window.__BSA_READ_ONLY__ || !id || !amount)return;
    try{
      const p=readProgress(),day=new Date().toLocaleDateString('en-CA');
      const eventId=kind+':'+id;
      if(p.events.some(e=>e.id===eventId))return;
      const earned=p.events.filter(e=>e.day===day&&e.kind===kind).reduce((n,e)=>n+Math.max(0,Number(e.xp)||0),0);
      const xp=Math.min(amount,Math.max(0,dailyLimit-earned));
      if(xp<=0)return;
      p.events.push({id:eventId,day,kind,xp,at:Date.now()});
      localStorage.setItem(PROGRESS_KEY,JSON.stringify(p));
      window.dispatchEvent(new Event('bsa-progress-updated'));
    }catch(e){console.warn('Activity XP not saved',e);}
  }
  function grantFlashcardReviewXp(cardId){
    if(!cardId)return;
    const day=new Date().toLocaleDateString('en-CA');
    // 3 XP for a distinct card each day; up to 45 XP/day.
    grantActivityXp('flashcard',day+':'+cardId,3,45);
  }
