    const [showTime,setShowTime]=useState(false);
    const [showReset,setShowReset]=useState(false);
    const subjects=scope==='all'?(data.subjects||[]):(data.subjects||[]).filter(s=>s.id===data.activeId);
    const roll=(getter)=>subjects.reduce((n,s)=>n+getter(s),0);
    const qCorrect=roll(s=>(s.quizzes||[]).reduce((n,q)=>n+Math.max(0,Number(q.score)||0),0));
    const qItems=roll(s=>(s.quizzes||[]).reduce((n,q)=>n+Math.max(0,Number(q.items)||0),0));
    const qSessions=roll(s=>(s.quizzes||[]).length);
    const pGot=roll(s=>(s.psets||[]).reduce((n,set)=>n+(set.problems||[]).filter(p=>p.st==='got').length,0));
    const pMiss=roll(s=>(s.psets||[]).reduce((n,set)=>n+(set.problems||[]).filter(p=>p.st==='miss').length,0));
    const due=roll(s=>(s.cards||[]).filter(c=>c.srs&&c.srs.due&&c.srs.due<=today()).length);
    const unresolved=roll(s=>(s.mistakes||[]).filter(m=>m.status!=='Cleared').length);
    const assessed=roll(s=>(s.cards||[]).filter(c=>['known','again','hard'].includes(c.conf)).length);
    const known=roll(s=>(s.cards||[]).filter(c=>c.conf==='known').length);
    const materialTopics=subjects.flatMap(s=>smartTopicStats(s).map(x=>({...x,subject:s}))).filter(x=>x.topic);
    const priority=materialTopics.filter(x=>x.observations>0||x.mistakes>0||x.dueCards>0).slice().sort((a,b)=>b.score-a.score).slice(0,5);
    const unassessed=materialTopics.filter(x=>!x.observations).length;
    const logged=roll(s=>(s.days||[]).reduce((n,d)=>n+Math.max(0,Number(d.mins)||0),0));
    const finished=roll(s=>(s.sessions||[]).filter(x=>x.done).reduce((n,x)=>n+Math.max(0,Number(x.mins)||0),0));
