      if(!window.confirm('Reset recorded study minutes for '+(scope==='all'?'all subjects':'this subject')+'? This cannot reconstruct untracked time. Export a backup first.'))return;
      update(null,d=>{for(const sub of d.subjects){if(targets.includes(sub.id))for(const day of sub.days||[])day.mins=0;}});
